package com.xauusd.mobileengine; import android.graphics.*;import android.view.*;import java.util.*; public class CandleChartView extends View{Paint p=new Paint(1);ArrayList<Candle> cs=new ArrayList<>();double bid,ask;String state="CONNECTING";public CandleChartView(android.content.Context c){super(c);setBackgroundColor(Color.rgb(10,12,15));}public void setData(Candle[] a){cs.clear();if(a!=null)Collections.addAll(cs,a);invalidate();}public void setTick(double b,double a,String s){bid=b;ask=a;state=s;invalidate();}protected void onDraw(Canvas x){float L=24,T=105,R=getWidth()-105,B=getHeight()-50;x.drawColor(Color.rgb(10,12,15));p.setTextSize(28);p.setColor(Color.WHITE);x.drawText("XAUUSD • M1",L,38,p);p.setTextSize(20);x.drawText(state,L,70,p);if(cs.isEmpty()){p.setColor(Color.YELLOW);x.drawText("Menunggu candle Biquote...",L,getHeight()/2,p);return;}double lo=1e99,hi=-1e99;for(Candle c:cs){lo=Math.min(lo,c.l);hi=Math.max(hi,c.h);}double rg=Math.max(hi-lo,.0001),gap=(R-L)/cs.size(),w=gap*.7;for(int i=0;i<cs.size();i++){Candle c=cs.get(i);float cx=(float)(L+i*gap+gap/2),yh=(float)(T+(hi-c.h)/rg*(B-T)),yl=(float)(T+(hi-c.l)/rg*(B-T)),yo=(float)(T+(hi-c.o)/rg*(B-T)),yc=(float)(T+(hi-c.c)/rg*(B-T));p.setColor(c.c>=c.o?Color.rgb(0,210,120):Color.rgb(255,70,70));p.setStrokeWidth(2);x.drawLine(cx,yh,cx,yl,p);x.drawRect(cx-(float)w/2,Math.min(yo,yc),cx+(float)w/2,Math.max(yo,yc)+1,p);}p.setTextSize(18);p.setColor(Color.WHITE);x.drawText(String.format(java.util.Locale.US,"BID %.2f",bid),R+4,T+20,p);x.drawText(String.format(java.util.Locale.US,"ASK %.2f",ask),R+4,T+48,p);x.drawText(String.format(java.util.Locale.US,"%.2f",hi),R+4,T+78,p);x.drawText(String.format(java.util.Locale.US,"%.2f",lo),R+4,B,p);}}